func TestD141_ClonePreparedConfigsDialContainerResolverProxy(t *testing.T) {
	sourceEnroll, err := json.MarshalIndent(map[string]any{
		"agent_release":             "0.1.0",
		"boot_id_file":              "/etc/vpn-node/boot-id",
		"control_url":               "https://portal.example.invalid:8443",
		"datapath":                  map[string]string{"member_ingress": "fvmb0", "snat": "198.51.100.20", "uplink": "fvup0"},
		"heartbeat_seconds":         5,
		"host_reserve_bps":          1000000,
		"identity_dir":              "/var/lib/vpn-node/identity",
		"journal_dir":               "/var/lib/vpn-node/update-journal",
		"lock_path":                 "/var/lib/vpn-node/update.lock",
		"netbird_backend":           "kernel",
		"observation_seconds":       5,
		"poll_seconds":              5,
		"release_id":                "00000000-0000-7000-8000-000000000001",
		"server_ca_file":            "/etc/vpn-node/ca.pem",
		"state_dir":                 "/var/lib/vpn-node/state",
		"test_mode":                 true,
		"trust_bundle":              "/etc/vpn-node/trust.json",
		"updater_config":            "/etc/vpn-node/updater-recover.json",
		"updater_recover":           "/usr/local/bin/fvpn-updater",
		"watchdog_interval_seconds": 5,
		"watchdog_stale_seconds":    30,
	}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	sourceRun, err := json.MarshalIndent(map[string]any{
		"agent_release": "0.1.0",
		"boot_id_file":  "/etc/vpn-node/boot-id",
		"control_url":   "https://127.0.0.1:9445",
		"datapath":      map[string]string{"member_ingress": "fvmb0", "snat": "198.51.100.20", "uplink": "fvup0"},
		"dns": map[string]any{
			"resolver_credentials_file": "/etc/vpn-node/resolver-credentials.json",
			"resolvers": []any{map[string]string{
				"admin_url": "http://127.0.0.1:8080",
				"dns_addr":  "127.0.0.1:53",
				"id":        "lab",
			}},
		},
		"heartbeat_seconds":         1,
		"host_reserve_bps":          1000000,
		"identity_dir":              "/var/lib/vpn-node/identity",
		"journal_dir":               "/var/lib/vpn-node/update-journal",
		"lock_path":                 "/var/lib/vpn-node/update.lock",
		"netbird_backend":           "kernel",
		"observation_seconds":       1,
		"poll_seconds":              1,
		"release_id":                "00000000-0000-7000-8000-000000000001",
		"server_ca_file":            "/etc/vpn-node/ca.pem",
		"state_dir":                 "/var/lib/vpn-node/state",
		"test_mode":                 true,
		"test_timing_path":          "/var/lib/vpn-node/e2e/isolation-operations.jsonl",
		"trust_bundle":              "/etc/vpn-node/trust.json",
		"updater_config":            "/etc/vpn-node/updater-recover.json",
		"updater_recover":           "/usr/local/bin/fvpn-updater",
		"watchdog_interval_seconds": 5,
		"watchdog_stale_seconds":    30,
	}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}

	const enrollPath = "etc/agent-enroll.json"
	const runPath = "etc/agent-run.json"
	const releasePath = "var/e2e/agent-00000000-0000-7000-8000-000000000001.json"
	durableFiles := map[string][]byte{
		"etc/machine-id":         []byte("0123456789abcdef0123456789abcdef\n"),
		"var/identity/node.json": []byte("{\"node_id\":\"00000000-0000-7000-8000-000000000002\"}\n"),
		"var/identity/cert.pem":  []byte("TEST ONLY - NOT A SECRET cert\n"),
		"var/identity/key.pem":   []byte("TEST ONLY - NOT A SECRET key\n"),
		"var/state/agent.db":     []byte("TEST ONLY durable sqlite state bytes"),
		"var/e2e/agent-selected": []byte("/usr/local\n"),
	}
	writeFiles := func(t *testing.T, base string, files map[string][]byte) {
		t.Helper()
		for path, data := range files {
			path = filepath.Join(base, path)
			if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(path, data, 0600); err != nil {
				t.Fatal(err)
			}
		}
	}
	readFile := func(t *testing.T, base, path string) []byte {
		t.Helper()
		raw, err := os.ReadFile(filepath.Join(base, path))
		if err != nil {
			t.Fatal(err)
		}
		return raw
	}
	decode := func(t *testing.T, raw []byte) map[string]any {
		t.Helper()
		var fields map[string]any
		d := json.NewDecoder(bytes.NewReader(raw))
		d.UseNumber()
		if err := d.Decode(&fields); err != nil {
			t.Fatal(err)
		}
		return fields
	}
	checkDurable := func(t *testing.T, base string) {
		t.Helper()
		for path, want := range durableFiles {
			if got := readFile(t, base, path); !bytes.Equal(got, want) {
				t.Fatalf("durable file %s changed", path)
			}
		}
	}
	for _, mode := range []struct {
		name  string
		clone bool
		snat  string
	}{
		{name: "clone", clone: true, snat: "198.51.100.23"},
		{name: "fresh", clone: false, snat: "198.51.100.22"},
	} {
		for _, format := range []string{"formatted", "compact"} {
			t.Run(mode.name+"/"+format, func(t *testing.T) {
				base := t.TempDir()
				files := map[string][]byte{enrollPath: sourceEnroll, runPath: sourceRun}
				if mode.clone {
					release := sourceRun
					if format == "compact" {
						// candidateConfig writes release configs with json.Marshal.
						var err error
						release, err = json.Marshal(decode(t, sourceRun))
						if err != nil {
							t.Fatal(err)
						}
						if bytes.Contains(release, []byte("\n")) {
							t.Fatal("release fixture is not compact")
						}
					}
					files[releasePath] = release
				} else if format == "compact" {
					for path, raw := range files {
						var compact bytes.Buffer
						if err := json.Compact(&compact, raw); err != nil {
							t.Fatal(err)
						}
						files[path] = compact.Bytes()
					}
				}
				writeFiles(t, base, files)
				writeFiles(t, base, durableFiles)
				if err := prepareExitSlotConfigs(base, mode.snat, mode.clone); err != nil {
					t.Fatal(err)
				}
				for path, before := range files {
					want := decode(t, before)
					if path == enrollPath || path == runPath {
						want["datapath"].(map[string]any)["snat"] = mode.snat
					}
					if path == runPath || path == releasePath {
						want["control_url"] = "https://127.0.0.1:9444"
					}
					// Compare complete decoded objects, including every key and
					// nested DNS value. Serialization need not preserve whitespace.
					got := decode(t, readFile(t, base, path))
					if !reflect.DeepEqual(got, want) {
						t.Errorf("%s: values changed outside the authorized field matrix\ngot: %#v\nwant: %#v", path, got, want)
					}
				}
				checkDurable(t, base)
			})
		}
	}
	// Exercise the same file preparation path without invoking startExitSlot or
	// Docker. A rejected file must not be overwritten; durable bytes stay intact.
	for _, invalid := range []struct{ name, raw string }{
		{"malformed", `{"datapath":`},
		{"null-config", `null`},
		{"array-config", `[]`},
		{"missing-datapath", `{"control_url":"https://127.0.0.1:9445"}`},
		{"null-datapath", `{"datapath":null}`},
		{"array-datapath", `{"datapath":[]}`},
	} {
		for _, path := range []string{enrollPath, runPath, releasePath} {
			t.Run("refuse/"+invalid.name+"/"+path, func(t *testing.T) {
				base := t.TempDir()
				files := map[string][]byte{enrollPath: sourceEnroll, runPath: sourceRun, releasePath: sourceRun}
				files[path] = []byte(invalid.raw)
				writeFiles(t, base, files)
				writeFiles(t, base, durableFiles)
				if err := prepareExitSlotConfigs(base, "198.51.100.23", true); err == nil {
					t.Fatal("accepted invalid config")
				}
				if got := readFile(t, base, path); !bytes.Equal(got, files[path]) {
					t.Fatal("rejected config was overwritten")
				}
				checkDurable(t, base)
			})
		}
	}
}

func (r *runner) secondExit(ctx context.Context) {
	rec := Record{ID: "second-exit", Title: "Second real exit enrollment and independent resolver", Spec: []string{"§6", "§19 AT09", "F3-03"}, Status: StatusBlocked}
	defer func() { r.record(rec) }()
	note := recPathNote(&rec)
	s := &Stack{lab: r.lab}
	if err := s.StartSecondExit(ctx); err != nil {
		note("start", err.Error())
		return
	}
	admin := r.mustAdmin(ctx)
	if admin == nil {
		note("login", "failed")
		return
	}
	node, err := s.EnrollAt(ctx, BrowserSession{Client: admin.http, CSRF: admin.csrf}, "TEST ONLY second real exit", "node2")
	if err != nil {
		note("enroll", err.Error())
		return
	}
	note("distinct_identity", boolText(node.NodeID != r.nodeID && node.IncarnationID != r.incID))
	wait, cancel := context.WithTimeout(ctx, 90*time.Second)
	defer cancel()
	var detail map[string]json.RawMessage
	ready := waitUntil(wait, time.Second, func() bool {
		res, e := s.Call(wait, BrowserSession{Client: admin.http, CSRF: admin.csrf}, "GET", "/api/v1/admin/nodes/"+node.NodeID.String(), nil, nil)
		if e != nil || res.Status != 200 || json.Unmarshal(res.Body, &detail) != nil {
			return false
		}
		return string(detail["provisioning_state"]) == `"ready"`
	})
	for _, key := range []string{"provisioning_state", "safety_status", "data_health", "applied_config_generation"} {
		note(key, string(detail[key]))
	}
	raw, e := r.lab.docker(r.lab.prefix+"-node2", "nft", "-j", "list", "table", "inet", "fvpn")
	note("independent_nft_table", boolText(e == nil && len(raw) > 0))
	note("scope", "real second node hook; publication and simultaneous two-exit traffic remain harness scenarios, physical topology and boot flavours need operator runs")
	if ready && node.NodeID != r.nodeID && node.IncarnationID != r.incID && e == nil {
		rec.Status = StatusPass
	} else {
		note("owner", "w3-devstack-e2e hook / w2-agent-core readiness; see exact state")
	}
}

package e2e

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestRedact_StripsSecrets(t *testing.T) {
	home := "/" + "home/someone"
	live := "sk_" + "live_abc"
	gh := "gh" + "p_abc"
	key := "-----BEGIN " + "OPENSSH PRIVATE KEY-----\nsecret\n-----END " + "OPENSSH PRIVATE KEY-----"
	code := "user_" + "code=AAAA-BBBB"
	in := "path=" + home + "/key postgres://fvpn:s3cret@db/fvpn Bearer tok \"setup_key\":\"abc\" " + live + " " + gh + " " + code + "\n" + key
	out := Redact(in)
	for _, banned := range []string{home, "s3cret", "Bearer tok", "abc", "sk_" + "live_", "gh" + "p_", "BEGIN " + "OPENSSH", "AAAA-BBBB"} {
		if strings.Contains(out, banned) {
			t.Fatalf("redaction left %q in %s", banned, out)
		}
	}
}

func TestWrite_RoundTrip(t *testing.T) {
	dir := t.TempDir()
	rec := Record{
		ID: "at-sample", Title: "sample", Spec: []string{"§19 AT06"}, Status: StatusPass,
		Observations: []Observation{{Name: "token", Detail: "length 43 path=" + "/" + "home/someone/token"}},
	}
	if err := Write(dir, rec); err != nil {
		t.Fatal(err)
	}
	b, err := os.ReadFile(filepath.Join(dir, "at-sample.md"))
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), "/"+"home/") || !strings.Contains(string(b), "Status: pass") {
		t.Fatalf("summary: %s", b)
	}
}

func TestSEC02_WriteRedactsIdentitySubjects(t *testing.T) {
	dir := t.TempDir()
	rec := Record{ID: "identity", Status: StatusBlocked, RunID: "test-run", SourceCommit: "test-commit"}
	for _, name := range []string{"portal_sub", "netbird_user_id", "peer_user_id", "external_user_id"} {
		rec.Observations = append(rec.Observations, Observation{Name: name, Detail: "synthetic-private-subject"})
	}
	rec.Observations = append(rec.Observations, Observation{Name: "same_subject", Detail: "true"})
	if err := Write(dir, rec); err != nil {
		t.Fatal(err)
	}
	for _, ext := range []string{".json", ".md"} {
		raw, err := os.ReadFile(filepath.Join(dir, rec.ID+ext))
		if err != nil {
			t.Fatal(err)
		}
		if strings.Contains(string(raw), "synthetic-private-subject") || !strings.Contains(string(raw), "same_subject") || !strings.Contains(string(raw), "test-run") {
			t.Fatalf("unsafe or incomplete evidence: %s", raw)
		}
	}
}

// The follow-up campaign's archived failures are part of the public artifact.
func TestCommittedFixtureEvidence_ValidAndHygieneClean(t *testing.T) {
	root := "../../docs/e2e/runs"
	if _, err := os.Stat(root); os.IsNotExist(err) {
		t.Skip("no committed follow-up fixture records")
	}
	records := 0
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if strings.HasPrefix(filepath.Base(filepath.Dir(path)), "2026-") && d.Name() != "followup16" && d.Name() != "followup17" && d.Name() != "followup18" && d.Name() != "followup19" && d.Name() != "followup20" && d.Name() != "followup21" && d.Name() != "followup22" && d.Name() != "followup23" && d.Name() != "followup24" && d.Name() != "followup25" && d.Name() != "followup26" && d.Name() != "followup27" && d.Name() != "followup29" && d.Name() != "followup30" && d.Name() != "followup31" && d.Name() != "followup32" && d.Name() != "followup33" && d.Name() != "followup34" && d.Name() != "followup35" && d.Name() != "followup36" && d.Name() != "followup37" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.Contains(path, "/followup") {
			return nil
		}
		raw, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		// Follow-up 27 keeps large captures losslessly compressed. Scan the
		// original bytes under their logical extension, never compressed noise.
		if strings.HasSuffix(path, ".gz") {
			reader, err := gzip.NewReader(bytes.NewReader(raw))
			if err != nil {
				return err
			}
			raw, err = io.ReadAll(io.LimitReader(reader, (256<<20)+1))
			closeErr := reader.Close()
			if err != nil {
				return err
			}
			if closeErr != nil {
				return closeErr
			}
			if len(raw) > 256<<20 {
				t.Fatalf("oversized compressed capture: %s", path)
			}
			path = strings.TrimSuffix(path, ".gz")
		}
		if filepath.Ext(path) == ".jsonl" && (strings.Contains(path, "/followup22/") || strings.Contains(path, "/followup23/") || strings.Contains(path, "/followup24/") || strings.Contains(path, "/followup25/") || strings.Contains(path, "/followup26/") || strings.Contains(path, "/followup27/")) {
			if len(raw) == 0 && emptyCaptureCertified(path) {
				return nil
			}
			for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
				var header map[string]json.RawMessage
				if json.Unmarshal([]byte(line), &header) != nil || header["packet"] == nil || header["timestamp"] == nil || header["header_error"] != nil {
					t.Errorf("invalid header evidence: %s", path)
				}
				for _, key := range []string{"payload", "data", "publicKey", "privateKey", "hostname", "mac"} {
					if header[key] != nil {
						t.Errorf("non-header evidence: %s", path)
					}
				}
			}
		}
		if filepath.Ext(path) == ".json" && filepath.Base(path) == "analysis.json" && (strings.Contains(path, "/followup22/") || strings.Contains(path, "/followup23/") || strings.Contains(path, "/followup24/") || strings.Contains(path, "/followup25/") || strings.Contains(path, "/followup26/") || strings.Contains(path, "/followup27/")) {
			var a struct {
				Schema string            `json:"schema"`
				Rows   []json.RawMessage `json:"rows"`
			}
			if json.Unmarshal(raw, &a) != nil || a.Schema != "native-capture-analysis-v1" || len(a.Rows) < 7 {
				t.Errorf("invalid native analysis: %s", path)
			}
		} else if filepath.Ext(path) == ".json" {
			var rec Record
			if json.Unmarshal(raw, &rec) != nil || rec.ID == "" || rec.RunID == "" || len(rec.SourceCommit) != 40 {
				t.Errorf("invalid fixture record: %s", path)
			}
			switch rec.Status {
			case StatusPass, StatusBlocked, StatusFail:
			default:
				t.Errorf("invalid claim: %s", path)
			}
			records++
		}
		for _, bad := range []string{"/ho" + "me/", "BEGIN " + "EC PRIVATE KEY", "BEGIN " + "RSA PRIVATE KEY", "BEGIN " + "OPENSSH PRIVATE KEY", "sk_" + "live_", "gh" + "p_", "gh" + "o_", "user_code=", "\"password\":", "\"setup_key\":"} {
			if strings.Contains(string(raw), bad) {
				t.Errorf("unsafe committed evidence: %s", path)
			}
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if records == 0 {
		t.Fatal("no fixture records scanned")
	}
}

// A stopped zero-packet capture is valid evidence, including an attempt that
// failed before its first request. Require its original capture receipt;
// arbitrary empty JSONL files must not silently pass hygiene.
func emptyCaptureCertified(path string) bool {
	role := strings.Split(filepath.Base(path), ".")[0]
	id := filepath.Base(filepath.Dir(path))
	root := filepath.Dir(filepath.Dir(filepath.Dir(path)))
	raw, err := os.ReadFile(filepath.Join(root, id+".json"))
	if err != nil {
		return false
	}
	var record Record
	if json.Unmarshal(raw, &record) != nil {
		return false
	}
	for _, o := range record.Observations {
		if o.Name != "capture" {
			continue
		}
		var capture struct {
			Points map[string]struct {
				Captured int  `json:"captured"`
				Drops    int  `json:"kernel_drops"`
				OK       bool `json:"statistics_ok"`
				Stopped  bool `json:"process_stopped"`
				Receipt  struct {
					Bytes string `json:"bytes"`
					SHA   string `json:"sha256"`
				} `json:"private_pcap_receipt"`
			} `json:"points"`
		}
		if json.Unmarshal([]byte(o.Detail), &capture) != nil {
			return false
		}
		point, ok := capture.Points[role]
		return ok && point.Captured == 0 && point.Drops == 0 && point.OK && point.Stopped && point.Receipt.Bytes == "24" && len(point.Receipt.SHA) == 64
	}
	return false
}

package meter

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/google/uuid"

	"github.com/TED-H-com/Freedom-VPN/node/enforce"
	"github.com/TED-H-com/Freedom-VPN/node/internal/usagestore"
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
)

// Directions of forward_admission_v1 counters (§10.1). DNS directions are
// not listed: those counters are a different namespace (D-019).
const (
	DirUpload   = "upload"
	DirDownload = "download"
)

// ErrHold means the wall clock stepped backwards by less than one sample
// interval. The sample is skipped so the interval cannot go negative (§10.9).
var ErrHold = fmt.Errorf("meter: wall clock jitter, sample held")

// Observation is one read of the kernel counters and the binding snapshot
// that explains them (§10.2, §10.5).
type Observation struct {
	Counters map[string]enforce.CounterValue
	Bindings []enforce.Binding
	// BootID is the host boot identity. A change means the kernel counters
	// were rebuilt even when the numbers happen to look continuous (§10.7).
	BootID string
}

// CounterName is the nftables counter name enforce uses for one device
// direction. DNS counters use a different prefix and are not usage.
func CounterName(device uuid.UUID, direction string) string {
	hexID := strings.ReplaceAll(device.String(), "-", "")
	switch direction {
	case DirUpload:
		return "u_" + hexID
	case DirDownload:
		return "d_" + hexID
	default:
		return ""
	}
}

func parseUsageCounter(name string) (uuid.UUID, string, bool) {
	var rest, dir string
	switch {
	case strings.HasPrefix(name, "u_"):
		rest, dir = name[len("u_"):], DirUpload
	case strings.HasPrefix(name, "d_"):
		rest, dir = name[len("d_"):], DirDownload
	default:
		return uuid.Nil, "", false
	}
	// Reject the DNS prefixes nu_ and nd_. "nu_" does not start with "u_",
	// but a short or dashed name is still not a device id.
	if len(rest) != 32 {
		return uuid.Nil, "", false
	}
	canon := rest[0:8] + "-" + rest[8:12] + "-" + rest[12:16] + "-" + rest[16:20] + "-" + rest[20:32]
	id, err := uuid.Parse(canon)
	if err != nil {
		return uuid.Nil, "", false
	}
	if strings.ReplaceAll(id.String(), "-", "") != rest {
		return uuid.Nil, "", false
	}
	return id, dir, true
}

type indexed struct {
	byDevice map[uuid.UUID]enforce.Binding
	conflict map[uuid.UUID]bool
}

func indexBindings(bindings []enforce.Binding) indexed {
	out := indexed{
		byDevice: make(map[uuid.UUID]enforce.Binding, len(bindings)),
		conflict: map[uuid.UUID]bool{},
	}
	for _, b := range bindings {
		prev, ok := out.byDevice[b.DeviceID]
		if ok && (prev.MemberID != b.MemberID || prev.BindingRevision != b.BindingRevision) {
			out.conflict[b.DeviceID] = true
		}
		out.byDevice[b.DeviceID] = b
	}
	return out
}

// usageCounters keeps only forward_admission_v1 device counters (D-019).
func usageCounters(obs Observation) []usagestore.Counter {
	idx := indexBindings(obs.Bindings)
	names := make([]string, 0, len(obs.Counters))
	for name := range obs.Counters {
		if _, _, ok := parseUsageCounter(name); ok {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	out := make([]usagestore.Counter, 0, len(names))
	for _, name := range names {
		dev, dir, _ := parseUsageCounter(name)
		v := obs.Counters[name]
		b := idx.byDevice[dev]
		// Two bindings for one device disagree. The bytes cannot be
		// attributed, so the revision stays zero and the sample becomes
		// a gap (§10.2, §10.7).
		if idx.conflict[dev] {
			b = enforce.Binding{}
		}
		out = append(out, usagestore.Counter{
			Name: name, DeviceID: dev, Direction: dir,
			Packets: v.Packets, Bytes: v.Bytes,
			MemberID: b.MemberID, BindingRevision: b.BindingRevision,
		})
	}
	return out
}

func counterMap(list []usagestore.Counter) map[string]enforce.CounterValue {
	out := make(map[string]enforce.CounterValue, len(list))
	for _, c := range list {
		out[c.Name] = enforce.CounterValue{Packets: c.Packets, Bytes: c.Bytes}
	}
	return out
}

func bootChanged(stored, current string) bool {
	if stored == "" && current == "" {
		return false
	}
	return stored != current
}

type plan struct {
	commit usagestore.Commit
	hold   bool
	noop   bool
}

// eventInterval enforces D-130 (2026-10-31): every newly minted interval has
// UTC whole-microsecond endpoints and is at least one microsecond wide, so
// central persistence cannot collapse it. Without a checkpoint, use the
// microsecond before end. Otherwise retain the truncated checkpoint as start
// and advance end if needed, even on clock rollback. Callers checkpoint the
// returned end so consecutive samples stay contiguous. Sealed events are never
// changed; a legacy nanosecond checkpoint is truncated only for the new start.
func eventInterval(start, end time.Time) (time.Time, time.Time) {
	start = start.UTC().Truncate(time.Microsecond)
	end = end.UTC().Truncate(time.Microsecond)
	if start.IsZero() {
		start = end.Add(-time.Microsecond)
	}
	if !end.After(start) {
		end = start.Add(time.Microsecond)
	}
	return start, end
}

// planContinuity decides whether a process start may keep the open meter
// epoch (§10.7). A short restart with the same boot id and counters that
// have not gone backwards continues the epoch. Anything else opens a new
// epoch and, when bytes may have been lost, a gap event.
func planContinuity(head usagestore.Head, obs Observation, now time.Time) (plan, error) {
	now = now.UTC()
	cur := usageCounters(obs)
	if head.OpenEpoch == uuid.Nil {
		return planBaseline(head, cur, now, obs.BootID), nil
	}
	if !bootChanged(head.BootID, obs.BootID) && len(enforce.DetectResets(counterMap(head.Counters), counterMap(cur))) == 0 {
		return plan{noop: true}, nil
	}
	return planSwitch(head, obs, cur, now, true, DefaultSampleInterval)
}

func planBaseline(head usagestore.Head, cur []usagestore.Counter, now time.Time, bootID string) plan {
	start, end := eventInterval(head.LastSample, now)
	id := uuid.Must(uuid.NewV7())
	reason := "baseline"
	if head.HasHistory {
		if head.LastCloseReason == "final_sample" {
			reason = "after_final_sample"
		} else {
			reason = "continuity_unknown"
		}
	}
	c := usagestore.Commit{
		Counters:  cur,
		Open:      &usagestore.NewEpoch{ID: id, Reason: reason, BootID: bootID},
		BootID:    bootID,
		SampledAt: end,
	}
	// A clean final sample already checkpointed the previous epoch. The new
	// baseline is the counters as they are, not a claim that they are zero
	// (§13.6 step 11). Unknown bytes exist only when this is the first
	// ledger and the counters are already non-zero, or the previous epoch
	// was not closed cleanly.
	needGap := false
	gapReason := ""
	switch {
	case !head.HasHistory && anyBytes(cur):
		needGap = true
		gapReason = string(api.UsageGapReasonUnknown)
	case head.HasHistory && head.LastCloseReason != "final_sample":
		needGap = true
		gapReason = string(api.UsageGapReasonUnknown)
	}
	if needGap {
		c.Event = &usagestore.Draft{
			EpochID:   id,
			Start:     start,
			End:       end,
			Quality:   string(api.UsageQualityGap),
			GapReason: gapReason,
			Detail:    "unknown counter continuity",
		}
	} else if now.Before(end) {
		// A quiet reopen need not advance a checkpoint already at or ahead
		// of this clock reading: there is no interval to give minimum width.
		c.SampledAt = start
	}
	return plan{commit: c}
}

func anyBytes(list []usagestore.Counter) bool {
	for _, c := range list {
		if c.Bytes > 0 || c.Packets > 0 {
			return true
		}
	}
	return false
}

// planSample builds the next interval commit. final closes the epoch after
// the sample (§13.6 step 8).
func planSample(head usagestore.Head, obs Observation, now time.Time, interval time.Duration, final bool) (plan, error) {
	return planSampleWithBarrier(head, obs, now, interval, final, false)
}

func planSampleWithBarrier(head usagestore.Head, obs Observation, now time.Time, interval time.Duration, final, restart bool) (plan, error) {
	now = now.UTC()
	if head.OpenEpoch == uuid.Nil {
		if final {
			return plan{}, ErrNoEpoch
		}
		p, err := planContinuity(head, obs, now)
		return p, err
	}
	cur := usageCounters(obs)
	resets := enforce.DetectResets(counterMap(head.Counters), counterMap(cur))
	if bootChanged(head.BootID, obs.BootID) || len(resets) > 0 {
		// The switch commit closes the old epoch. When this is a final
		// sample the caller closes the fresh epoch afterwards so the next
		// process opens its own (§13.6 step 11).
		return planSwitch(head, obs, cur, now, false, interval)
	}
	if !head.LastSample.IsZero() && !now.After(head.LastSample) {
		if head.LastSample.Sub(now) <= interval {
			// A retry of FinalSample or a restart checkpoint after the
			// interval was already checkpointed still succeeds when the
			// readings have not changed. Changed counters wait for a
			// forward clock so those bytes are not abandoned (§10.9).
			if (final || restart) && sameReadings(head.Counters, cur) {
				c := usagestore.Commit{
					Epoch:     head.OpenEpoch,
					Counters:  head.Counters,
					BootID:    obs.BootID,
					SampledAt: head.LastSample,
				}
				if final {
					c.CloseEpoch = true
					c.CloseReason = "final_sample"
				}
				return plan{commit: c}, nil
			}
			return plan{hold: true}, nil
		}
		p, err := planClockGap(head, obs, now)
		if final {
			p.commit.CloseEpoch = true
			p.commit.CloseReason = "final_sample"
		}
		return p, err
	}
	end, estimated := stampEnd(head.LastSample, now, interval)
	if head.LastSample.IsZero() {
		end = now
		estimated = false
	}
	if !end.After(head.LastSample) && !head.LastSample.IsZero() {
		return plan{hold: true}, nil
	}
	start, end := eventInterval(head.LastSample, end)
	recs, mapping := attribute(head, cur, end)
	c := usagestore.Commit{
		Epoch:     head.OpenEpoch,
		Counters:  cur,
		BootID:    obs.BootID,
		SampledAt: end,
	}
	if len(recs) == 0 && !mapping && !estimated {
		c.Counters = cur
		if final {
			c.CloseEpoch = true
			c.CloseReason = "final_sample"
		}
		return plan{commit: c}, nil
	}
	d := usagestore.Draft{
		EpochID: head.OpenEpoch,
		Start:   start,
		End:     end,
		Records: recs,
		Quality: string(api.UsageQualityComplete),
	}
	switch {
	case mapping:
		d.Quality = string(api.UsageQualityGap)
		d.GapReason = string(api.UsageGapReasonUnknown)
		d.Detail = "mapping conflict"
		if !head.LastSample.IsZero() {
			t := head.LastSample
			d.LastCheckpoint = &t
		}
	case estimated:
		d.Quality = string(api.UsageQualityBoundaryEstimated)
	}
	c.Event = &d
	if final {
		c.CloseEpoch = true
		c.CloseReason = "final_sample"
	}
	return plan{commit: c}, nil
}

func planClockGap(head usagestore.Head, obs Observation, now time.Time) (plan, error) {
	cur := usageCounters(obs)
	start, end := eventInterval(head.LastSample, head.LastSample)
	t := head.LastSample
	c := usagestore.Commit{
		Epoch:     head.OpenEpoch,
		Counters:  cur,
		BootID:    obs.BootID,
		SampledAt: end,
		Event: &usagestore.Draft{
			EpochID:        head.OpenEpoch,
			Start:          start,
			End:            end,
			Quality:        string(api.UsageQualityGap),
			GapReason:      string(api.UsageGapReasonClockAnomaly),
			LastCheckpoint: &t,
			Detail:         "wall clock moved backwards",
		},
	}
	return plan{commit: c}, nil
}

func sameReadings(a, b []usagestore.Counter) bool {
	if len(a) != len(b) {
		return false
	}
	by := make(map[string]usagestore.Counter, len(b))
	for _, c := range b {
		by[c.Name] = c
	}
	for _, c := range a {
		d, ok := by[c.Name]
		if !ok || d.Packets != c.Packets || d.Bytes != c.Bytes {
			return false
		}
	}
	return true
}

func planSwitch(head usagestore.Head, obs Observation, cur []usagestore.Counter, now time.Time, opening bool, interval time.Duration) (plan, error) {
	reason := string(api.UsageGapReasonCounterDiscontinuity)
	detail := "counter discontinuity"
	if bootChanged(head.BootID, obs.BootID) {
		reason = string(api.UsageGapReasonPowerLoss)
		detail = "host boot changed"
	}
	// A boot change may have wrapped the counters back up. Apparent
	// increases are not trustworthy (§10.7). A single counter reset still
	// reports the other devices' non-negative deltas.
	var recs []usagestore.DraftRecord
	end := now
	estimated := false
	if !opening && !head.LastSample.IsZero() {
		end, estimated = stampEnd(head.LastSample, now, interval)
	}
	start, end := eventInterval(head.LastSample, end)
	if !opening && !head.LastSample.IsZero() {
		if !bootChanged(head.BootID, obs.BootID) {
			recs, _ = attribute(head, cur, end)
		}
	}
	var last *time.Time
	if !head.LastSample.IsZero() {
		t := head.LastSample
		last = &t
	}
	id := uuid.Must(uuid.NewV7())
	d := usagestore.Draft{
		EpochID:        head.OpenEpoch,
		Start:          start,
		End:            end,
		Quality:        string(api.UsageQualityGap),
		GapReason:      reason,
		LastCheckpoint: last,
		Records:        recs,
		Detail:         detail,
	}
	if estimated {
		// Gap wins over boundary_estimated: missing bytes are the fact
		// the ledger has to keep (§10.7, §10.9).
		d.Detail += "; boundary sample missed"
	}
	boot := obs.BootID
	if boot == "" {
		boot = head.BootID
	}
	return plan{commit: usagestore.Commit{
		Event:       &d,
		Counters:    cur,
		CloseEpoch:  true,
		CloseReason: reason,
		Open:        &usagestore.NewEpoch{ID: id, Reason: reason, BootID: boot},
		BootID:      boot,
		SampledAt:   end,
	}}, nil
}

func attribute(head usagestore.Head, cur []usagestore.Counter, end time.Time) ([]usagestore.DraftRecord, bool) {
	prev := make(map[string]usagestore.Counter, len(head.Counters))
	for _, c := range head.Counters {
		prev[c.Name] = c
	}
	type acc struct {
		up, down uint64
		member   uuid.UUID
		rev      uint64
		oldMem   uuid.UUID
		oldRev   uint64
		hadOld   bool
	}
	by := map[uuid.UUID]*acc{}
	order := []uuid.UUID{}
	touch := func(id uuid.UUID) *acc {
		a, ok := by[id]
		if ok {
			return a
		}
		a = &acc{}
		by[id] = a
		order = append(order, id)
		return a
	}
	for _, c := range cur {
		p, ok := prev[c.Name]
		var delta uint64
		if !ok {
			delta = c.Bytes
		} else if c.Bytes >= p.Bytes && c.Packets >= p.Packets {
			delta = c.Bytes - p.Bytes
		} else {
			continue
		}
		a := touch(c.DeviceID)
		if c.Direction == DirUpload {
			a.up += delta
		} else {
			a.down += delta
		}
		if c.MemberID != uuid.Nil {
			a.member = c.MemberID
			a.rev = c.BindingRevision
		}
		if ok && (p.MemberID != uuid.Nil || p.BindingRevision != 0) {
			a.hadOld = true
			a.oldMem = p.MemberID
			a.oldRev = p.BindingRevision
		}
	}
	sort.Slice(order, func(i, j int) bool { return order[i].String() < order[j].String() })
	period := usagestore.PeriodID(head.LastSample)
	if head.LastSample.IsZero() {
		period = usagestore.PeriodID(end)
	}
	var recs []usagestore.DraftRecord
	mapping := false
	for _, id := range order {
		a := by[id]
		if a.up == 0 && a.down == 0 {
			continue
		}
		if a.member == uuid.Nil || a.rev == 0 || (a.hadOld && (a.oldMem != a.member || a.oldRev != a.rev)) {
			mapping = true
			continue
		}
		recs = append(recs, usagestore.DraftRecord{
			MemberID: a.member, DeviceID: id, BindingRevision: a.rev,
			PeriodID: period, Upload: a.up, Download: a.down,
		})
	}
	return recs, mapping
}

package meter

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"sync"
	"time"

	"github.com/google/uuid"

	"github.com/TED-H-com/Freedom-VPN/node/internal/usagestore"
)

// Fault steps observed by the store hook (§10.5, AT16). A crash here is
// before any database write.
const (
	StepRead = "sample.read"
	StepPlan = "sample.plan"
)

// ReasonMeterPath is the Health reason when the counter source cannot be
// read. Member forwarding stops; the control channel is not this package's
// concern (§10.7).
const ReasonMeterPath = "meter_path_invalid"

var (
	// ErrNoEpoch means FinalSample found no open meter epoch (§13.6 step 8).
	ErrNoEpoch = errors.New("meter: no open meter epoch to finish")
	// ErrBusy means a sample is already running.
	ErrBusy = errors.New("meter: sample already in progress")
	// ErrClosed means Close has been called.
	ErrClosed = errors.New("meter: closed")
	// ErrPaused means Barrier is in force. ResumeSampling clears it.
	ErrPaused = errors.New("meter: sampling is paused")
)

// Source reads kernel counters and the binding snapshot. The agent supplies
// the nftables reader. Tests supply a fake.
type Source interface {
	Read(ctx context.Context) (Observation, error)
}

// Config builds a Meter. Store and Source are required. Interval defaults
// to 10s (§10.5, 建議預設).
type Config struct {
	NodeID        uuid.UUID
	IncarnationID uuid.UUID
	Store         *usagestore.Store
	Source        Source
	Interval      time.Duration
	Now           func() time.Time
	// PreserveClosedEpoch keeps a completed final_sample closed at blocked
	// startup. PrepareSampling must open the next epoch before admission.
	PreserveClosedEpoch bool
	// ExistingEpochOnly prepares same-boot adoption without writing the ledger.
	// A closed epoch, reset or reboot requires withdrawal before reconciliation.
	ExistingEpochOnly bool
	// Mono is the monotonic clock used to space samples (§10.5). Nil means
	// time.Now, whose Sub uses the monotonic reading. Timestamps stored on
	// events still come from Now.
	Mono   func() time.Time
	Logger *slog.Logger
}

// Controller is the surface the updater and the forwarding gate call
// (§13.6 steps 8 and 11, §10.7). The agent process owns the node lock and
// the actual forwarding change. This package only reports the decision.
type Controller interface {
	Barrier(ctx context.Context) error
	FinalSample(ctx context.Context) error
	Health(ctx context.Context) (usagestore.Health, error)
}

// Meter samples forward-admission counters into the usage store.
type Meter struct {
	store    *usagestore.Store
	src      Source
	interval time.Duration
	now      func() time.Time
	mono     func() time.Time
	log      *slog.Logger
	lastMono time.Time

	mu           sync.Mutex
	cond         *sync.Cond
	paused       bool
	sampling     bool
	closed       bool
	inFinal      bool
	sourceFailed bool
	wake         chan struct{}
}

var _ Controller = (*Meter)(nil)

// New checks the open meter epoch against the current counters (§10.7) and
// returns a meter ready to sample. A source that cannot be read fails the
// constructor: the agent must not forward when it cannot meter.
func New(cfg Config) (*Meter, error) { return NewContext(context.Background(), cfg) }

// NewContext bounds startup reconciliation by the caller's local budget.
func NewContext(ctx context.Context, cfg Config) (*Meter, error) {
	if cfg.Store == nil || cfg.Source == nil || cfg.NodeID == uuid.Nil || cfg.IncarnationID == uuid.Nil {
		return nil, fmt.Errorf("meter: store, source, node and incarnation are required")
	}
	id, inc := cfg.Store.Identity()
	if id != cfg.NodeID || inc != cfg.IncarnationID {
		return nil, fmt.Errorf("meter: store identity does not match the meter")
	}
	interval := cfg.Interval
	if interval <= 0 {
		interval = DefaultSampleInterval
	}
	now := cfg.Now
	if now == nil {
		now = time.Now
	}
	mono := cfg.Mono
	if mono == nil {
		mono = time.Now
	}
	log := cfg.Logger
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	m := &Meter{
		store: cfg.Store, src: cfg.Source, interval: interval, now: now, mono: mono, log: log,
		wake: make(chan struct{}, 1),
	}
	m.cond = sync.NewCond(&m.mu)
	if cfg.ExistingEpochOnly {
		obs, err := m.src.Read(ctx)
		if err != nil {
			return nil, err
		}
		head, err := m.store.Head(ctx)
		if err != nil {
			return nil, err
		}
		p, err := planContinuity(head, obs, m.nowUTC())
		if err != nil {
			return nil, err
		}
		if !p.noop {
			return nil, fmt.Errorf("meter: adoption requires a continuous open epoch")
		}
		m.paused = true
		m.markSampled()
		return m, nil
	}
	if cfg.PreserveClosedEpoch {
		if _, err := m.store.ClosedCheckpoint(ctx); err == nil {
			m.paused = true
			return m, nil
		}
	}
	if err := m.reconcile(ctx); err != nil {
		return nil, err
	}
	return m, nil
}

func (m *Meter) nowUTC() time.Time { return m.now().UTC() }

func (m *Meter) reconcile(ctx context.Context) error {
	obs, err := m.src.Read(ctx)
	if err != nil {
		m.noteSource(err)
		return err
	}
	head, err := m.store.Head(ctx)
	if err != nil {
		m.store.NotePersistFailure()
		return err
	}
	p, err := planContinuity(head, obs, m.nowUTC())
	if err != nil {
		return err
	}
	if p.noop {
		m.clearSource()
		m.markSampled()
		return nil
	}
	if err := m.persist(ctx, p, obs.BootID); err != nil {
		return err
	}
	m.markSampled()
	return nil
}

// Sample takes one interval. A quiet interval updates the checkpoint time
// and does not invent an event (§10.5).
func (m *Meter) Sample(ctx context.Context) error {
	return m.sample(ctx, false)
}

func (m *Meter) sample(ctx context.Context, final bool) error {
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return ErrClosed
	}
	if m.paused && !m.inFinal && !final {
		m.mu.Unlock()
		return ErrPaused
	}
	if m.sampling {
		m.mu.Unlock()
		return ErrBusy
	}
	m.sampling = true
	restart := m.inFinal && !final
	m.mu.Unlock()
	defer func() {
		m.mu.Lock()
		m.sampling = false
		m.cond.Broadcast()
		m.mu.Unlock()
	}()

	if err := m.store.Fault(StepRead); err != nil {
		return err
	}
	obs, err := m.src.Read(ctx)
	if err != nil {
		m.noteSource(err)
		return err
	}
	if err := m.store.Fault(StepPlan); err != nil {
		return err
	}
	head, err := m.store.Head(ctx)
	if err != nil {
		m.store.NotePersistFailure()
		return err
	}
	if final && head.OpenEpoch == uuid.Nil {
		m.clearSource()
		return ErrNoEpoch
	}
	p, err := planSampleWithBarrier(head, obs, m.nowUTC(), m.interval, final, restart)
	if err != nil {
		return err
	}
	if p.hold {
		return ErrHold
	}
	if p.noop {
		m.clearSource()
		m.markSampled()
		return nil
	}
	if err := m.persist(ctx, p, obs.BootID); err != nil {
		return err
	}
	m.markSampled()
	if final && p.commit.Open != nil {
		// The switch left a fresh epoch open. Close it without an event
		// so the next process does not treat the handoff as a crash
		// (§13.6 step 11).
		head2, err := m.store.Head(ctx)
		if err != nil {
			m.store.NotePersistFailure()
			return err
		}
		closePlan := plan{commit: usagestore.Commit{
			Epoch:       head2.OpenEpoch,
			Counters:    head2.Counters,
			BootID:      obs.BootID,
			CloseEpoch:  true,
			CloseReason: "final_sample",
			SampledAt:   head2.LastSample,
		}}
		if err := m.persist(ctx, closePlan, obs.BootID); err != nil {
			return err
		}
	}
	return nil
}

func (m *Meter) persist(ctx context.Context, p plan, boot string) error {
	seq, err := m.store.Commit(ctx, p.commit)
	if err != nil {
		if errors.Is(err, usagestore.ErrInjectedCrash) {
			// A crash after commit left the row durable. Do not flag the
			// ledger as unwritable (§10.5, AT16).
			if seq != 0 || p.commit.Event == nil {
				m.store.NotePersistSuccess()
			}
			return err
		}
		m.store.NotePersistFailure()
		return err
	}
	m.store.NotePersistSuccess()
	m.clearSource()
	if p.commit.Open != nil {
		m.log.Info("meter epoch opened",
			"epoch_id", p.commit.Open.ID.String(),
			"reason", p.commit.Open.Reason,
			"boot_id", boot,
			"event_seq", seq)
	} else if p.commit.CloseEpoch {
		m.log.Info("meter epoch closed",
			"epoch_id", p.commit.Epoch.String(),
			"reason", p.commit.CloseReason,
			"event_seq", seq)
	}
	return nil
}

// Barrier pauses the sampler and waits until the in-flight sample finishes
// (§13.6 step 8). ResumeSampling continues a sample loop that has not yet
// taken the final sample.
func (m *Meter) Barrier(ctx context.Context) error {
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return ErrClosed
	}
	m.paused = true
	if !m.sampling {
		m.mu.Unlock()
		return nil
	}
	stop := make(chan struct{})
	go func() {
		select {
		case <-ctx.Done():
			m.mu.Lock()
			m.cond.Broadcast()
			m.mu.Unlock()
		case <-stop:
		}
	}()
	for m.sampling {
		m.cond.Wait()
		if ctx.Err() != nil && m.sampling {
			close(stop)
			m.mu.Unlock()
			return ctx.Err()
		}
	}
	m.mu.Unlock()
	close(stop)
	return nil
}

// FinalSample takes the closing sample and shuts the meter epoch (§13.6
// step 8). The next process opens a new epoch at the checkpointed counters.
func (m *Meter) FinalSample(ctx context.Context) error {
	return m.pausedSample(ctx, true)
}

// CheckpointForRestart persists the last observed delta without closing the
// epoch or clearing the kernel counters. A same-boot successor accounts for
// bytes admitted during the process gap using the existing continuity path.
// Updater withdrawal must still use FinalSample.
func (m *Meter) CheckpointForRestart(ctx context.Context) error {
	return m.pausedSample(ctx, false)
}

func (m *Meter) pausedSample(ctx context.Context, final bool) error {
	if err := m.Barrier(ctx); err != nil {
		return err
	}
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return ErrClosed
	}
	m.inFinal = true
	m.mu.Unlock()
	defer func() {
		m.mu.Lock()
		m.inFinal = false
		m.mu.Unlock()
	}()
	return m.sample(ctx, final)
}

// PrepareSampling durably opens the next epoch from a real counter read while
// keeping the sampler paused. The caller must keep forwarding blocked until
// this succeeds, then install its admission rules and call ResumeSampling.
// Otherwise the first admitted bytes could become the new epoch's baseline.
func (m *Meter) PrepareSampling(ctx context.Context) error {
	if err := m.Barrier(ctx); err != nil {
		return err
	}
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return ErrClosed
	}
	if m.sampling {
		m.mu.Unlock()
		return ErrBusy
	}
	m.sampling = true
	m.mu.Unlock()
	defer func() {
		m.mu.Lock()
		m.sampling = false
		m.cond.Broadcast()
		m.mu.Unlock()
	}()
	return m.reconcile(ctx)
}

// ResumeSampling clears a barrier after any required PrepareSampling.
func (m *Meter) ResumeSampling() {
	m.mu.Lock()
	m.paused = false
	m.mu.Unlock()
	m.poke()
}

// Health is the forwarding gate (§10.7, §10.8). Store caps win when both
// a cap and a source failure are set. A source failure alone stops
// forwarding with ReasonMeterPath.
func (m *Meter) Health(ctx context.Context) (usagestore.Health, error) {
	h, err := m.store.EvaluateGate(ctx)
	if err != nil {
		return usagestore.Health{}, err
	}
	m.mu.Lock()
	failed := m.sourceFailed
	m.mu.Unlock()
	if failed && h.Reason == "" {
		h.ForwardingAllowed = false
		h.Reason = ReasonMeterPath
		h.Detail = "the meter could not read counters; member forwarding is stopped (§10.7)"
	}
	return h, nil
}

// Run samples until ctx is cancelled. The wait is the earlier of the sample
// interval and the next UTC month boundary (§10.5, §10.9).
func (m *Meter) Run(ctx context.Context) error {
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		m.mu.Lock()
		paused := m.paused || m.closed
		m.mu.Unlock()
		if !paused {
			err := m.Sample(ctx)
			if err != nil && ctx.Err() == nil && !errors.Is(err, ErrHold) && !errors.Is(err, ErrPaused) && !errors.Is(err, ErrBusy) {
				m.log.Warn("usage sample failed", "err", err.Error())
			}
		}
		delay := m.nextWait(ctx)
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-m.wake:
			timer.Stop()
		case <-timer.C:
		}
	}
}

// Close stops the sampler. It does not close the store.
func (m *Meter) Close() {
	m.mu.Lock()
	m.closed = true
	m.paused = true
	m.cond.Broadcast()
	m.mu.Unlock()
	m.poke()
}

// nextWait is the earlier of the remaining monotonic sample interval and
// the next UTC month boundary (§10.5, §10.9). A wall-clock jump does not
// shorten or stretch the interval. Once the wall clock is already at or
// past the boundary, the sampler wakes immediately so the interval can be
// stamped there.
func (m *Meter) nextWait(ctx context.Context) time.Duration {
	head, err := m.store.Head(ctx)
	if err != nil {
		return m.interval
	}
	nowWall := m.nowUTC()
	m.mu.Lock()
	last := m.lastMono
	m.mu.Unlock()
	var monoWait time.Duration
	if !last.IsZero() {
		elapsed := m.mono().Sub(last)
		if elapsed < 0 {
			elapsed = 0
		}
		monoWait = m.interval - elapsed
		if monoWait < 0 {
			monoWait = 0
		}
	} else {
		monoWait = NextDelay(head.LastSample, nowWall, m.interval)
	}
	if head.LastSample.IsZero() {
		return monoWait
	}
	boundary := nextBoundaryAfter(head.LastSample)
	if !nowWall.Before(boundary) {
		return 0
	}
	until := boundary.Sub(nowWall)
	if until < monoWait {
		return until
	}
	return monoWait
}

func (m *Meter) markSampled() {
	m.mu.Lock()
	m.lastMono = m.mono()
	m.mu.Unlock()
}

func (m *Meter) poke() {
	select {
	case m.wake <- struct{}{}:
	default:
	}
}

func (m *Meter) noteSource(err error) {
	m.mu.Lock()
	m.sourceFailed = true
	m.mu.Unlock()
	m.log.Warn("usage counter read failed", "err", err.Error())
}

func (m *Meter) clearSource() {
	m.mu.Lock()
	m.sourceFailed = false
	m.mu.Unlock()
}

