func TestCheckpointForRestartAtSameMicrosecond(t *testing.T) {
	ctx := context.Background()
	// Exact whole-microsecond wall clock (Nanosecond()%1000 == 0).
	startAt := time.Date(2026, 11, 4, 19, 39, 55, 21658000, time.UTC)
	clk := &clock{t: startAt}
	src := &fakeSrc{}
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 1, upB: 2048, upP: 1}))
	m, s := start(t, src, clk, usagestore.Options{})
	defer m.Close()

	// Counter reset opens a new epoch E2 with LastSample == clk.Now() (exact microsecond).
	clk.Set(startAt.Add(2 * time.Second))
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 1, upB: 2048, upP: 0}))
	if err := m.Sample(ctx); err != nil {
		t.Fatal(err)
	}
	headBefore, err := s.Head(ctx)
	if err != nil || headBefore.OpenEpoch == uuid.Nil {
		t.Fatalf("head before checkpoint: %+v %v", headBefore, err)
	}

	// Same-boot restart checkpoint at the same microsecond with unchanged readings
	// must succeed and keep E2 open, just as FinalSample succeeds with CloseEpoch=true.
	if err := m.CheckpointForRestart(ctx); err != nil {
		t.Fatalf("CheckpointForRestart failed at exact microsecond boundary: %v", err)
	}
	headAfter, err := s.Head(ctx)
	if err != nil || headAfter.OpenEpoch != headBefore.OpenEpoch {
		t.Fatalf("CheckpointForRestart did not preserve open epoch: before=%s after=%+v err=%v",
			headBefore.OpenEpoch, headAfter, err)
	}

	// Changed counters at the same microsecond must still hold (§10.9) so new
	// bytes wait for a forward clock rather than being abandoned.
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 1, upB: 4096, upP: 2}))
	if err := m.CheckpointForRestart(ctx); !errors.Is(err, ErrHold) {
		t.Fatalf("CheckpointForRestart with changed counters at same microsecond: got %v, want ErrHold", err)
	}
}

func TestFinalSampleAndBarrier(t *testing.T) {
	ctx := context.Background()
	clk := &clock{t: time.Date(2026, 10, 28, 14, 0, 0, 0, time.UTC)}
	src := &fakeSrc{}
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 2, upB: 5, upP: 1}))
	m, s := start(t, src, clk, usagestore.Options{})
	// Non-zero at first open is a gap, then the final sample closes.
	clk.Set(clk.Now().Add(10 * time.Second))
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 2, upB: 25, upP: 3}))
	if err := m.FinalSample(ctx); err != nil {
		t.Fatal(err)
	}
	head, err := s.Head(ctx)
	if err != nil || head.OpenEpoch != uuid.Nil || head.LastCloseReason != "final_sample" {
		t.Fatalf("%+v %v", head, err)
	}
	finalEv := loadEvent(t, s, 2)
	if finalEv.Quality != api.UsageQualityComplete || uint64(finalEv.Records[0].UploadBytes) != 20 {
		t.Fatalf("final delta %+v", finalEv)
	}
	m.Close()
	_ = s.Close()
	s2, err := usagestore.Open(s.Path(), nodeID, incID, usagestore.Options{Now: clk.Now})
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 2, upB: 25, upP: 3}))
	m2, err := New(Config{NodeID: nodeID, IncarnationID: incID, Store: s2, Source: src, Interval: 10 * time.Second, Now: clk.Now})
	if err != nil {
		t.Fatal(err)
	}
	defer m2.Close()
	if _, err := s2.Event(ctx, 3); err == nil {
		t.Fatal("clean handoff emitted a gap")
	}
	clk.Set(clk.Now().Add(10 * time.Second))
	src.set(observe("boot", reading{dev: devA, mem: memA, rev: 2, upB: 40, upP: 4}))
	if err := m2.Sample(ctx); err != nil {
		t.Fatal(err)
	}
	next := loadEvent(t, s2, 3)
	if uint64(next.Records[0].UploadBytes) != 15 {
		t.Fatalf("recounted from zero: %+v", next.Records[0])
	}

	block := make(chan struct{})
	src.block = block
	src.hit = make(chan struct{}, 1)
	clk.Set(clk.Now().Add(10 * time.Second))
	done := make(chan error, 1)
	go func() { done <- m2.Sample(ctx) }()
	select {
	case <-src.hit:
	case <-time.After(2 * time.Second):
		t.Fatal("sample did not start")
	}
	bdone := make(chan error, 1)
	go func() { bdone <- m2.Barrier(ctx) }()
	select {
	case err := <-bdone:
		t.Fatalf("barrier returned early: %v", err)
	case <-time.After(30 * time.Millisecond):
	}
	close(block)
	if err := <-bdone; err != nil {
		t.Fatal(err)
	}
	if err := <-done; err != nil {
		t.Fatal(err)
	}
	if err := m2.Sample(ctx); !errors.Is(err, ErrPaused) {
		t.Fatalf("after barrier: %v", err)
	}
	m2.ResumeSampling()
	src.block = nil
	clk.Set(clk.Now().Add(10 * time.Second))
	if err := m2.Sample(ctx); err != nil {
		t.Fatal(err)
	}
}

